; Generated by build tooling - CPU exception, hardware IRQ and yield stubs.
;
; The whole CPU state of an interrupted task ends up pushed on that task's
; own stack, so a context switch is just a matter of resuming on a
; different stack pointer. Both dispatchers therefore RETURN the stack to
; continue on, and the stubs load it with 'mov esp, eax'.
[BITS 32]
section .text
extern isr_handler
extern irq_handler
extern yield_handler

