; Software interrupt 0x30: a task asking to be rescheduled right now.
; No EOI here - no PIC was involved.
yield_entry:
    cli
    push dword 0
    push dword 48
    jmp yield_common


; Saves the segment registers and general purpose registers, switches to the
; kernel data segment, and hands %1 a pointer to the resulting frame.
%macro ENTER_HANDLER 0
    pusha                           ; edi esi ebp esp ebx edx ecx eax
    mov     ax, ds
    push    eax                     ; save the caller's data segment
    mov     ax, 0x10
    mov     ds, ax
    mov     es, ax
    mov     fs, ax
    mov     gs, ax
    push    esp                     ; registers_t *
%endmacro

; The handler returned the stack to resume on in eax. Loading it also discards
; the pointer argument pushed above.
%macro LEAVE_HANDLER 0
    mov     esp, eax
    pop     eax
    mov     ds, ax
    mov     es, ax
    mov     fs, ax
    mov     gs, ax
    popa
    add     esp, 8                  ; drop int_no and err_code
    iret
%endmacro

isr_common:
    ENTER_HANDLER
    call    isr_handler
    LEAVE_HANDLER

irq_common:
    ENTER_HANDLER
    call    irq_handler
    LEAVE_HANDLER

yield_common:
    ENTER_HANDLER
    call    yield_handler
    LEAVE_HANDLER
